// Writes src/migrations.ts: the API's SQL migrations as Text modules Wrangler bundles, since
// Workers have no file system. test/migrations.test.ts fails if this file falls behind.
import { readdir, writeFile } from 'node:fs/promises';

const dir = new URL('../api/src/platform/database/migrations/', import.meta.url);
const files = (await readdir(dir)).filter((f) => /^\d{4}_[a-z0-9_]+\.sql$/.test(f)).sort();
const lines = [
  '// Generated by generate-migrations.mjs from apps/api/src/platform/database/migrations.',
  "import type { Migration } from '../../api/src/platform/database/migrator.ts';",
  ...files.map(
    (file, i) => `import m${i} from '../../api/src/platform/database/migrations/${file}';`,
  ),
  '',
  'export const MIGRATIONS: readonly Migration[] = [',
  ...files.map((file, i) => `  { version: '${file.replace(/\.sql$/, '')}', sql: m${i} },`),
  '];',
  '',
];
await writeFile(new URL('./src/migrations.ts', import.meta.url), lines.join('\n'));
console.log(`src/migrations.ts: ${files.length} migrations`);
